package io.github.ningpp.compat;

import java.util.Comparator;

/**
 * Replacement for System.Collections.Generic.ReferenceEqualityComparer (generated by
 * CSharpToJava converter): an equality comparer that uses reference identity instead
 * of Object.equals(Object) and Object.hashCode().
 *
 * @param <T> The type of the objects compared by this comparer.
 */
public final class ReferenceEqualityComparer<T> implements Comparator<T>, IEqualityComparer<T> {

    /** The single shared instance behind every getInstance()/getDefault() call. */
    private static final ReferenceEqualityComparer<?> INSTANCE = new ReferenceEqualityComparer<>();

    private ReferenceEqualityComparer() {
    }

    /**
     * The shared instance of the comparer (C# ReferenceEqualityComparer.Instance).
     *
     * @param <T> The type of the objects compared by this comparer.
     * @return The shared comparer instance.
     */
    @SuppressWarnings("unchecked")
    public static <T> ReferenceEqualityComparer<T> getInstance() {
        return (ReferenceEqualityComparer<T>) INSTANCE;
    }

    /**
     * The shared instance of the comparer — alias of {@link #getInstance()} for call
     * sites converted from a static Default-like property.
     *
     * @param <T> The type of the objects compared by this comparer.
     * @return The shared comparer instance.
     */
    @SuppressWarnings("unchecked")
    public static <T> ReferenceEqualityComparer<T> getDefault() {
        return (ReferenceEqualityComparer<T>) INSTANCE;
    }

    /**
     * Determines whether the two references point at the same object.
     *
     * @param x The first reference to compare.
     * @param y The second reference to compare.
     * @return true when both references are the same object (or both are null).
     */
    @Override
    public boolean equals(T x, T y) {
        return x == y;
    }

    /**
     * Returns the identity based hash code of the object, which never calls the
     * object's own Object.hashCode() override.
     *
     * @param obj The object whose identity hash code is requested.
     * @return The identity hash code, or 0 when the object is null.
     */
    @Override
    public int hashCode(T obj) {
        return System.identityHashCode(obj);
    }

    /**
     * Orders two references by their identity hash code. Reference-equal objects
     * always compare as equal, so this ordering is consistent with
     * {@link #equals(Object, Object)}.
     *
     * @param x The first reference to compare.
     * @param y The second reference to compare.
     * @return A negative integer, zero, or a positive integer as x is less than,
     *         equal to, or greater than y.
     */
    @Override
    public int compare(T x, T y) {
        if (x == y) return 0;
        return Integer.compare(System.identityHashCode(x), System.identityHashCode(y));
    }
}
